Let the radius of the Earth be 1.  By spherical coordinates, we can place the initial point at
\[A = (\sin 60^\circ \cos (-45^\circ), \sin 60^\circ \sin (-45^\circ), \cos 60^\circ) = \left( \frac{\sqrt{6}}{4}, -\frac{\sqrt{6}}{4}, \frac{1}{2} \right),\]and the final point at
\[B = (\sin 60^\circ \cos 45^\circ, \sin 60^\circ \sin 45^\circ, \cos 60^\circ) = \left( \frac{\sqrt{6}}{4}, \frac{\sqrt{6}}{4}, \frac{1}{2} \right).\]Then the shortest path from $A$ to $B$ along the surface of the Earth is arc $AB,$ where the center of the arc is the center of the Earth $O.$  By symmetry, the northernmost point on this arc is the midpoint of the arc.  Let this midpoint be $C,$ so $C$ lies in the $xz$-plane.

[asy]
import three;
import solids;

size(200);
currentprojection = perspective(6,3,2);

triple A, B, C, M, O;

A = (sqrt(6)/4,-sqrt(6)/4,1/2);
B = (sqrt(6)/4,sqrt(6)/4,1/2);
C = (sqrt(15)/5,0,sqrt(10)/5);
O = (0,0,0);
M = (A + B)/2;

draw(surface(sphere(1)),gray(0.9),nolight);
draw((-1.2,0,0)--(1.2,0,0),Arrow3(6));
draw((0,-1.2,0)--(0,1.2,0),Arrow3(6));
draw((0,0,-1.2)--(0,0,1.2),Arrow3(6));
draw(O--A);
draw(O--B);
draw((1,0,0)..(1/sqrt(2),0,1/sqrt(2))..(0,0,1));
draw((1/sqrt(2),1/sqrt(2),0)..(1,0,0)..(1/sqrt(2),-1/sqrt(2),0),red);
draw((1/sqrt(2),1/sqrt(2),0)..(Sin(75)*Cos(45),Sin(75)*Sin(45),Cos(75))..B,red);
draw((1/sqrt(2),-1/sqrt(2),0)..(Sin(75)*Cos(45),-Sin(75)*Sin(45),Cos(75))..A,red);
draw(O--(1/sqrt(2),1/sqrt(2),0));
draw(O--(1/sqrt(2),-1/sqrt(2),0));
draw(A..(sqrt(15)/5,0,sqrt(10)/5)..B,red);
draw(A--B);
draw(O--C);

label("$x$", (1.2,0,0), SW);
label("$y$", (0,1.2,0), E);
label("$z$", (0,0,1.2), N);
label("$30^\circ$", 0.2*(Sin(75)*Cos(45),Sin(75)*Sin(45),Cos(75)) + (0,0.1,0), red);
label("$30^\circ$", 0.2*(Sin(75)*Cos(45),-Sin(75)*Sin(45),Cos(75)) + (0,-0.15,0), red);
label("$45^\circ$", (0.4,0.15,0), red);
label("$45^\circ$", (0.5,-0.2,0), red);

dot("$A$", A, NW);
dot("$B$", B, NE);
dot("$C$", C, NW);
dot("$M$", M, SW);
[/asy]

